insert into companies
  (id, name, tier, booths, company_type, hq, ask, who, bio, fit, opening_line, asks, watch_out, is_default, archived)
values
  ('yamazen', 'Yamazen', 'A', '{"338536"}', 'Importer', 'Schaumburg, IL', 'Importer with its own Tooling Division. Brother SPEEDIO is a BT30/BBT30 world. Ask who runs Tooling; pitch a value shrink-fit line and holders on the Brother/Matsuura demos.', null, 'Japanese trading house and exclusive US importer for Brother SPEEDIO, Matsuura, Nidec Takisawa and JTEKT. Unusually for an importer it runs its own Tooling Division selling cutting tools and holders alongside machines, and it already distributes MST shrink-fit holders in the US.', 'They sell machines and tooling to the same customer, and the Brother SPEEDIO line is a BT30/BBT30 world where a light, well-balanced shrink holder is exactly right. They already believe in shrink fit because they sell MST. The opening is the price tier below MST.', 'You sell MST shrink fit today at the premium end. We build the same geometry at the value end, plus a $6,800 machine that makes the whole thing affordable for a five-machine SPEEDIO shop. Who runs your Tooling Division?', '{"Meet the Tooling Division manager, not machine sales","Would a value tier under MST cannibalize or expand their tooling revenue?","BT30/BBT30 holder package for SPEEDIO demo machines"}', 'They carry MST. Position as the tier below, for shops that will never buy MST, not as a replacement.', true, false),
  ('methods', 'Methods Machine Tools', 'A', '{"339033"}', 'Importer', 'Sudbury, MA', 'Yasda (HSK-E/A63), RoboDrill (BT30), Nakamura, plus an automation division. Ask for the tooling package on Yasda installs and a shrink+preset station in their cells.', null, 'One of the largest US machine tool importers: Nakamura-Tome, Yasda, OKK, Kiwa, FANUC RoboDrill and ROBOCUT, plus its own Methods Automation division building turnkey cells. Eight tech centers nationwide.', 'Yasda runs HSK-E and HSK-A63 at jig-bore precision where shrink fit is mandatory; RoboDrill is BT30 volume. Their automation division builds lights-out cells, and lights-out cells create the tool-setup bottleneck our presetter and shrink station solve.', 'Your Yasda customers run HSK-A63 at sub-micron and your RoboDrill customers run BT30 in volume. We make both, and we make the shrink machine and presetter that feed an unattended cell. What does the tooling package look like on a Yasda install today?', '{"Who specifies the tooling package on a Yasda or RoboDrill install?","Does Methods Automation have a tool-setup answer for its lights-out cells?","Free starter set for one tech-center demo machine"}', 'Big and slow. The realistic first win is a tech-center demo set, not a distribution agreement.', true, false),
  ('ellison', 'Ellison Technologies (at DN Solutions)', 'A', '{"338919"}', 'Dealer', 'Santa Fe Springs, CA', 'Largest DN dealer, CA/TX/Midwest/Southeast. Reception Tuesday 4–7 pm, happy hour daily at 4. Tooling packages on DVF 5-axis (HSK) installs.', 'Tim Gaylor · Monty Smith', 'Largest DN Solutions (Doosan) dealer in North America, covering California, Texas, the Midwest and Southeast, plus Heller and Halter robotics. No booth of its own; staff work the DN, Heller and Halter stands.', 'They install hundreds of DVF 5-axis machines a year, each needing 40 to 120 holders in the first month, and they are California-heavy, which is our home territory. A dealer bundle is the fastest volume path that needs no distributor agreement.', 'Every DVF you install goes out needing forty holders, and the customer buys them from whoever is standing there. We would like to be the tooling package on your demo machines, starting with one. Who owns that decision?', '{"Who decides the tooling package on a new DN install?","Free starter set for the California tech center","Co-branded shrink starter cell as an install add-on"}', 'Reception Tuesday 4–7 pm at the DN booth and a daily 4 pm happy hour. That is the moment, not a cold aisle approach at noon.', true, false),
  ('productivity', 'Productivity Inc. (at Haas, Makino, Matsuura)', 'A', '{"338100","338519","338630"}', 'Dealer', 'Minneapolis, MN', 'Minnesota/Iowa/Nebraska dealer for Haas, Makino, Matsuura, Hwacheon, Citizen. Sells tooling. They host customers at builder booths 9–noon; approach after lunch.', null, 'Upper Midwest dealer (Minnesota, Iowa, Nebraska, the Dakotas) for Haas, Makino, Matsuura, Hwacheon and Citizen, running a full tooling and workholding division with its own applications engineers.', 'A dealer that already sells tooling as a line of business is a distributor in everything but name, and their Makino and Matsuura customers are exactly the HSK shrink-fit buyers. One relationship covers five states.', 'You already sell tooling and workholding, not just machines. We are the value shrink-fit line with a machine cheap enough that your Haas customers can actually adopt it. What would it take to add a line?', '{"Who runs the tooling and workholding division?","Margin and stocking commitment they need on a new line","Demo shrink machine on loan for the Minneapolis showroom"}', 'They host their own customers at builder booths 9 to noon daily. Approach after lunch.', true, false),
  ('morris', 'Morris Group (at Okuma, Tsugami)', 'A', '{"338500","339410"}', 'Dealer', 'Windsor, CT', 'Okuma, Tsugami, Hardinge network across Northeast/Southeast/Midwest. Ask who owns tooling lines.', null, 'Family-owned group of machine tool distributors (Morris Midwest, Morris South, Morris Great Lakes) plus Tsugami America, the exclusive North American Tsugami importer. Okuma, Tsugami and Hardinge across the Northeast, Southeast and Midwest.', 'Three booths, one ownership. Okuma dealers install Capto and HSK machines; Tsugami is Swiss and mill-turn. A single conversation reaches a large slice of the eastern US installed base.', 'You have three stands here and three territories. We build shrink fit and presetting at a price your job-shop customers can say yes to on the same PO as the machine. Who owns tooling lines across the group?', '{"Is tooling decided per region or at group level?","Intro to whoever handles accessories on Okuma installs","Presetting for Tsugami gang and Swiss setups"}', 'Spread across three booths. Find the group-level person rather than pitching each stand.', true, false),
  ('absolute', 'Absolute Machine Tools', 'A', '{"339476"}', 'Importer', 'Lorain, OH', 'Ohio importer of You Ji / Tongtai / Johnford with a dealer network. Importer model means open to tooling bundles. You Ji VTL runs Capto and BT50.', null, 'Ohio importer of You Ji vertical turning lathes, Tongtai, Johnford and Quicktech, sold through a regional dealer network. Exhibiting under You Ji this year.', 'Importers survive on accessory and tooling margin because machine margin is thin. The You Ji VTL on their stand is built for Capto tooling and their Tongtai machining centers run BT40 and BT50. An importer with a dealer network is a distributor with extra steps.', 'You import machines and sell through dealers, which means your dealers already quote tooling with every machine. We would like to be the shrink-fit line on that quote, and we bring a $6,800 machine so the customer can actually use it.', '{"Do their dealers quote tooling today, and from whom?","Private-label or co-branded holder line for the Absolute network","Free starter set for the Ohio showroom"}', 'Mid-size, decisions are fast. Get the owner or a VP, not a booth demonstrator.', true, false),
  ('expand', 'Expand Machinery', 'A', '{"338045"}', 'Importer', 'Chatsworth, CA', 'California importer of Ganesh/Genturn/Genmill, BT40 value segment, close to our LA base. Natural first bundle partner.', null, 'California importer behind Ganesh, Genturn and Genmill: Swiss lathes, mill-turn and 3 to 5 axis machining centers aimed at the value end of the job-shop market.', 'Twenty miles from our LA base, selling to price-sensitive shops, BT40 value machines. Geography alone makes this the easiest partnership to service and the easiest to pilot.', 'We are based in LA, you are in Chatsworth, and we both sell to the shop that cannot justify a Haimer. Can we put a shrink cell in your showroom and split the story?', '{"Showroom shrink cell (U7 Pro plus 20 holders) on loan","Joint Southern California customer day after the show","Tooling package to quote with Genmill 5-axis"}', 'Small company, the owner decides. If you meet a salesperson, ask for the owner''s card.', true, false),
  ('msc', 'MSC Industrial Supply', 'A', '{"432228"}', 'Distributor', 'Melville, NY', 'National distributor, carries Haimer and Techniks. Long game. Ask for the metalworking category manager''s name and the new-line onboarding process.', null, 'The largest metalworking MRO distributor in the US, roughly 2.5 million SKUs, with vending and inventory-management programs inside customer plants. Already carries Haimer, Techniks and Kennametal toolholding.', 'The biggest distribution prize in the building and also the slowest. Realistic goal this week is not a line agreement; it is the metalworking category manager''s name and the written new-supplier process.', 'We are a shrink-fit manufacturer that just opened a US branch. I am not going to pitch you a line on a show floor. I want to know who your metalworking category manager is and what your new-supplier process actually looks like.', '{"Name and email of the toolholding category manager","New-supplier requirements: EDI, packaging, fill rate, insurance","Do they run a private-label toolholding program?"}', 'Booth staff are field sales, not category managers. Be honest that you want a contact and you will usually get one.', true, false),
  ('shars', 'Shars Tool', 'A', '{"134506"}', 'Distributor', 'Mokena, IL', 'Illinois value distributor that already sells import holders. A branded shrink-fit line plus the $6.8K machine fits their price tier.', null, 'Illinois value tooling distributor founded 1978, catalog and e-commerce, serving small shops with affordable imported tooling and measuring equipment. Already sells import holders under its own name.', 'Shars lives at exactly our price tier and already private-labels imported holders. Their customers cannot afford Haimer but would buy a cell at $6,800 plus holders. The most plausible private-label win of the week.', 'You already private-label imported holders. We make shrink fit, and we make the machine that makes shrink fit affordable for your customer. Would a Shars-branded shrink cell sell in your catalog?', '{"Shars-branded shrink-fit line","Would they carry the U7 Pro as a catalog item?","Volumes and price points they need to hit"}', 'East hall, away from the Tooling crowd. Do not skip it for the walk: a Tier A conversation in a Tier D location.', true, false),
  ('ths', 'Tool Holder Shop Inc.', 'A', '{"432097"}', 'Distributor', 'US (unconfirmed)', 'Directory entry reads "CNC machine tools tool holders distributor." Pure reseller. Ask what they source, what''s missing, whether they private-label.', null, 'Small dedicated toolholder reseller. The directory entry reads only "CNC machine tools tool holders distributor", which usually means a lean operation sourcing from several Asian makers.', 'A pure-play holder reseller has no machine business to protect and no brand loyalty to defend. If they source from Taiwan today, our price and our machine are both new arguments. Small enough to decide in the aisle.', 'You distribute holders and nothing else, so you know exactly where your gaps are. Ours is shrink fit plus the machine. What are you sourcing today and what can you not get?', '{"Who do they source from now, and what is missing?","Shrink fit under their own label","Minimum order and terms"}', 'Thin public information. Treat the first conversation as discovery, not a pitch.', true, false),
  ('accutek', 'Accutek', 'A', '{"431591"}', 'Private label', 'US', 'Import-style holder brand with hydraulic and presetting lines. Second-source shrink fit / HSK.', null, 'Toolholding and workholding brand covering CAT and BT holders, AccuClamp hydraulic chucks and presetting equipment under its own name. Listed under Tool Holders, Hydraulic Toolholders and Tool Presetting.', 'A brand selling hydraulic chucks and presetters with no visible shrink-fit line. That is the exact gap we fill, and their presetting listing means they already sell tool setup as a system.', 'You sell hydraulic and presetting but I do not see shrink fit in your line. We make it, we make the machine, and we are happy to put your name on both.', '{"Do they manufacture or source?","Private-label shrink-fit line under Accutek","Bundle our machine with their presetter"}', 'They may already have a shrink source. Ask what it is before pitching against it.', true, false),
  ('pac', 'PAC Precision Tools USA', 'A', '{"432061"}', 'Private label', 'US', 'Small holder brand. Make or source? Private-label shrink line.', null, 'Small US toolholder brand: CNC toolholders, collets and accessories including hydraulic. A one-line directory listing usually signals a sourcing-and-branding operation rather than a manufacturer.', 'If they source, they are a private-label customer. If they manufacture, they are a competitor worth understanding. Either answer is useful and takes one question.', 'Do you make these or source them? Either way, we make shrink fit in HSK, CAT and BT and we are looking for US brands to supply.', '{"Make or source?","Shrink-fit gap in the line","Who decides sourcing"}', 'Very small. The owner is likely at the booth.', true, false),
  ('delton', 'Delton International USA', 'A', '{"431573"}', 'Distributor', 'Rochester, MI', 'Michigan importer with US inventory. Add shrink fit and a machine.', null, 'Michigan-based one-stop importer of tooling and machine accessories, holding US inventory. Listed under hydraulic toolholders.', 'US inventory is the thing we do not have. A partner already warehousing in Michigan fixes our worst objection, lead time, without capital from us, and the Detroit belt is dense with 5-axis and HSK.', 'Our weakness is that we ship from China. Yours is that you have no shrink-fit line. We could fix both with consignment stock in your Michigan warehouse.', '{"Would they stock our holders on consignment?","What does the Michigan warehouse actually hold today?","Detroit-area customers running HSK"}', 'Ask about consignment terms carefully. Do not commit stock levels without the team.', true, false),
  ('royal', 'Royal Products', 'A', '{"431622"}', 'Private label', 'Hauppauge, NY', 'New York accessory brand that sells sourced lines under its own label. Shrink fit under the Royal name.', null, 'Long-established New York accessory manufacturer and brander: Quick-Grip collet chucks, Rota-Rack parts handling, mist collectors and CNC accessories, sold under the Royal name through distribution.', 'Royal''s model is putting its name on well-made accessories and pushing them through an established distributor network. They have the network; we have a category they do not carry.', 'Royal''s name on a shrink-fit line, our manufacturing behind it, and your distributors already have the customer. What is missing from your accessory line right now?', '{"Shrink fit under the Royal brand","How many distributors are in the network?","Their inspection requirements for a new supplier"}', 'Established, quality-proud brand. Lead with inspection certificates, not price.', true, false),
  ('omega', 'Omega TMM', 'A', '{"432220"}', 'Presetting', 'Fairport, NY', 'US-made presetters and a ShrinkSet station; they show Techniks and Parlec holders on their machines. They need holders, we need a US-made presetter to bundle. Mutual referral.', null, 'American manufacturer of tool presetters (Astra, Solis, Orion, Helios, Fortis, Exactus, EVO and the new SEDEO) plus a ShrinkSet shrink station and Optik software. Their booth displays partner holders from REGO-FIX, Walter, Techniks, Parlec, Tsugami, Caron and CMV.', 'The most interesting booth in the hall. They compete with us on presetting but publicly display other people''s holders on their machines, so they need holder partners. A US-made presetter paired with our holders and machine also answers the made-in-America objection.', 'You put Techniks and Parlec holders on your presetters. We make holders too, and unlike them we also make the shrink machine. What if your presetter and our shrink cell went out as one quote?', '{"Would they display HIPPSC holders on the SEDEO?","Joint bundle: US presetter plus our shrink machine and holders","Mutual referral: they refer shrink, we refer presetting"}', 'They are a presetting competitor. Keep the conversation on holders and bundling, not on our presetter line.', true, false),
  ('koma', 'Koma Precision', 'A', '{"338754"}', 'Importer', 'East Windsor, CT', 'Exclusive importer (Tsudakoma, Alberti) with its own presetters and loaders. Would they represent a shrink machine + holder line?', null, 'Since 1982 the exclusive North American importer for Tsudakoma rotary tables, Alberti and Romai angle heads, plus its own presetters and part loaders. A textbook exclusive-representation business.', 'Koma''s entire model is taking one excellent foreign line and owning it in North America. That is precisely the deal we want for the shrink machine, and they already sell presetters so they understand the tool-setup buyer.', 'Your business is being the North American arm of good foreign manufacturers. We are a good foreign manufacturer looking for exactly that. Would you look at representing a shrink-fit machine line?', '{"Exclusive North American representation of the shrink machine","How do they evaluate a new principal?","Does shrink fit conflict with anything they carry?"}', 'Exclusivity cuts both ways. Do not offer exclusivity without the team, but find out what they would want.', true, false),
  ('globalcnc', 'Global CNC Industries', 'A', '{"431815"}', 'Private label', 'Plymouth, MI', 'Turning-side holders (Capto/PSC/VDI), no milling shrink fit. Cross-referral or a private-label milling line.', null, 'US manufacturer of turning and mill-turn toolholding: static and driven holders, Capto and PSC, VDI and BMT, plus driven-tool repair. Also listed under tool crib software.', 'They own the lathe side and have no milling shrink-fit line. Zero product overlap, same customer, same distributors. Cross-referral or a private-label milling line, and both are easy asks because nothing competes.', 'You own turning, we own milling shrink fit, and we sell to the same shops. There is no overlap at all. Cross-refer, or put your name on a milling line?', '{"Cross-referral between turning and milling","Private-label milling shrink fit under Global CNC","Which distributors they sell through"}', 'US manufacturer: made-in-USA is part of their pitch, so a private label may be sensitive. Ask how they handle it.', true, false),
  ('platinum', 'Platinum Tooling', 'A', '{"432201"}', 'Importer', 'Prospect Heights, IL', 'Illinois importer of heimatec and Tecnicrafts. Shrink fit is a gap in their portfolio.', null, 'Importer and exclusive US agent for heimatec live tools and angle heads, Tecnicrafts collets and Henninger. Their business is adding European lines to a US sales network.', 'Their whole company is built on taking on new foreign lines, so the structural answer to "would you look at a line" is yes. Shrink fit is not in the portfolio and does not compete with live tooling.', 'You add European lines to a US network for a living. We are Chinese, which is a different conversation, so let me lead with the inspection data and the price.', '{"Do they take on non-European lines?","Shrink fit as a portfolio gap","What the sales network looks like by territory"}', 'Their brand is built on European engineering. Origin will be the first objection; have certificates ready.', true, false),
  ('iswiss', 'iSwiss', 'A', '{"431379"}', 'Distributor', 'US', 'Tool and workholding reseller, BIMU rep.', null, 'Supplier of tool and workholding plus cutting tools, and an authorized BIMU agent. Small reseller with a Swiss-machining lean.', 'Reseller with a precision-machining customer base. Small enough to move fast, and Swiss shops buy small HSK-E shrink holders that most suppliers do not stock.', 'Do your Swiss and precision customers ask for small shrink fit, HSK-E32 and E40? That is a size most people do not stock and we do.', '{"Demand for small HSK-E shrink fit in their base","Line-carry interest","Their territory"}', 'Small operation. Verify they actually sell holders rather than only cutting tools.', true, false),
  ('eurotech', 'Euro-Tech', 'A', '{"432272"}', 'Distributor', 'Brookfield, WI', 'Wisconsin importer of German tooling and workholding. Would they add a value shrink-fit line with a machine?', null, 'Wisconsin distributor of German-engineered tooling and workholding gages and accessories, including mechanical and hydraulic expansion arbors.', 'They already sell expansion arbors, which is adjacent clamping technology, so their customers already accept precision clamping as a category. Shrink fit is the same sale to the same buyer.', 'You sell hydraulic expansion arbors, so your customers already buy precision clamping. Shrink fit is the same buyer with a different technology, and we have the machine to go with it.', '{"Would they add a shrink-fit line?","Their Wisconsin and Midwest customer profile","Any conflict with existing German lines"}', 'German-line identity, same origin objection as Platinum.', true, false),
  ('friedl', 'T. Friedl Enterprises', 'A', '{"432258"}', 'Distributor', 'US', 'Importer-distributor (HAM drills, DTS). Same question: shrink fit gap.', null, 'Importer and distributor of HAM precision drills, Diamond Tooling Systems, Bipico band saw blades, Micron filters and TFE chuck jaws. A multi-line import house.', 'A multi-line importer with no holder line at all. Broad catalog, small company, fast decisions.', 'You import several lines already and none of them is toolholding. Would a shrink-fit line fit the same customers you sell drills to?', '{"Toolholding gap in their catalog","Sales channel and territory","Interest in the machine as well as holders"}', 'Small booth, possibly one or two people. Owner-level conversation is likely.', true, false),
  ('usshop', 'U S Shop Tools · ABS Import Tools', 'A', '{"432122","432083"}', 'Distributor', 'US', 'National import tooling distributors. Branded shrink fit plus machine at their tier.', null, 'Two national distributors of imported machine shop tooling and metalworking supplies, both selling the value tier through catalog and dealer channels.', 'Both already sell imported tooling at our price tier and both have already solved the origin objection for their customers. Low-friction conversations: they know the category, the only question is whether shrink fit sells for them.', 'You already sell imported tooling, so we can skip the part where origin is a problem. Does shrink fit move in your channel, and would a $6,800 machine make it move faster?', '{"Does shrink fit sell in their channel today?","Would they carry the machine as well as the holders?","Price points they need"}', 'Two separate companies with three booths between them. Budget twenty minutes each.', true, false),
  ('jmpp', 'JM Performance Products', 'A', '{"431961"}', 'Ally', 'Fairport Harbor, OH', 'High-torque retention knobs. Every CAT/BT holder needs a pull stud. Bundle their knobs with our holders; ask for their dealer list.', null, 'Maker of High Torque retention knobs and CNC spindle optimization products. Their pitch is that standard pull studs deform taper bores and cost accuracy, a story every toolholder buyer hears at their booth.', 'Perfect complement, zero competition. Every CAT and BT holder we sell needs a pull stud, and their sales pitch is about taper contact accuracy, which is also ours. Their distributor list is the real prize.', 'Every holder we sell needs a retention knob, and every knob you sell needs a holder. Our story is taper accuracy and so is yours. Should we be selling into each other''s channels?', '{"Bundle knobs with our holders","Introduction to their distributor network","Co-marketing on the taper-accuracy story"}', 'The only company at the show whose product physically attaches to ours. Do not leave without the distributor conversation.', true, false),
  ('fastems', 'Fastems', 'A', '{"338966"}', 'Automation', 'West Chester, OH', 'FMS and pallet automation; FMS users centralize tool setup. A presetter/shrink station inside their tool-storage flow.', 'Chris Hansen, Sales Mgr US & Canada West · chris.hansen@fastems.com', 'Finnish flexible manufacturing systems: pallet pools, FPS Stationary, ALD robotic loading cells and MMS control software interfacing to more than 90 machine brands. Their systems include central tool storage.', 'An FMS is the one place where tool setup is unambiguously the bottleneck: unattended machines cannot assemble their own tools. Fastems already manages tool data in MMS, so a shrink and preset station as a cell option is a real product conversation.', 'Your systems run unattended for a shift, but somebody still has to shrink and preset every tool by hand before that shift starts. Does MMS handle tool setup today, or does it stop at pallets?', '{"Does MMS handle tool data and setup, or stop at pallets?","Shrink plus preset station as an option in a Fastems cell","Who owns integration partnerships"}', 'Engineering-led company. Come with the integration question, not a price.', true, false),
  ('xometry', 'Xometry', 'A', '{"338368"}', 'Ally', 'North Bethesda, MD', 'Marketplace with thousands of partner shops. Ask about supplier-perks or tooling partner programs.', null, 'AI-driven manufacturing marketplace connecting buyers to thousands of partner machine shops across the US, now including the Thomas industrial platform.', 'Xometry does not buy tooling, but it has thousands of small partner shops and a supplier-perks program that exists to give them discounts. Getting into that program puts our holders in front of more job shops than any distributor could.', 'We do not want to sell to Xometry. We want to be a discount in your supplier perks program, in front of your partner shops. Who runs that?', '{"Who runs supplier perks or partner benefits?","What a tooling vendor needs to qualify","Do they share aggregate data on what their shops run?"}', 'Booth staff are marketplace sales focused on buyers. Ask specifically for the supplier network side.', true, false),
  ('jingdiao', 'Jingdiao North America', 'A', '{"339153"}', 'Ally', 'Mount Prospect, IL', 'Chinese machine OEM with a real US presence (Mount Prospect, IL). HSK-E32/A63 machines. Ask how they did it; offer holders for their demo machines.', null, 'US subsidiary of Beijing Jingdiao, a Chinese maker of high-speed precision 3 and 5 axis machining centers for graphite, mold and micro work. Runs a Chicago-area tech center with contract machining, selling direct plus dealers.', 'The best case study in the building: a Chinese manufacturer that built a real US presence, a tech center and a dealer network in a skeptical market. Their machines run HSK-E32 and HSK-A63, our shrink-fit sweet spot, so there is a product conversation too.', 'You did what we are trying to do. Before I pitch you anything, how long did it take to get American shops to take a Chinese machine seriously, and what would you skip if you started again?', '{"How they beat the origin objection, and how long it took","Which dealers said yes first and why","HIPPSC holders on their demo machines"}', 'An ally, not a prospect. Lead with curiosity, close with the demo-holder offer.', true, false),
  ('zcc', 'ZCC USA', 'A', '{"431938"}', 'Ally', 'Ann Arbor, MI', 'Chinese carbide brand in Ann Arbor that entered through "a select group of distributors" and never leads with origin. Ask which distributors, how long, what worked.', null, 'US arm of ZCC Cutting Tools, a large Chinese carbide manufacturer. Sells strictly through a selected group of qualified distributors, leans on ISO 9001 and German and Swiss production equipment in its messaging, and never leads with country of origin.', 'The distributor-only playbook we should probably copy, executed by a Chinese company facing the same objections. They know which US distributors will and will not take a Chinese line, and that list beats any market report.', 'You went distributor-only and never lead with origin. We are earlier on the same road. Which distributors were willing, and which ones would not take the call?', '{"Which distributor types said yes first","How long from first conversation to first stocking order","Would they ever bundle a non-competing holder line with their carbide?"}', 'Potential ally, zero product overlap (carbide versus holders). Be generous with what you share and they usually reciprocate.', true, false),
  ('cmtba', 'CMTBA (China Machine Tool & Tool Builders'' Assoc.)', 'A', '{"432580"}', 'Association', 'Beijing, China', 'International Associations row. Get the list of Chinese exhibitors and any joint events. Ally, not target.', null, 'The Chinese national industry association, in the International Associations row in West alongside TAMI (Taiwan), KOMMA (Korea), AMDM (Mexico) and AMTIL (Australia). Roughly 70 China-based companies exhibit at IMTS 2026.', 'One stop that maps every Chinese exhibitor at the show, who already has a US presence, and who holds US inventory. Also where to learn about any joint Chinese-exhibitor event during the week.', 'We are a Chinese manufacturer with a new US branch and no booth. Who else from China is here that we should be talking to, and is anything organized this week?', '{"Full list of Chinese exhibitors and booths","Any joint reception during the week","Which members already hold US inventory"}', 'Association staff, not salespeople. Ten minutes, collect information, move on.', true, false),
  ('okuma', 'Okuma America', 'B', '{"338500"}', 'Machine OEM', 'Charlotte, NC', 'Formal "Partners in Technology" program for tooling vendors. Ask how to join. Robot loaders and tower pallet changers need presetting.', 'Simon Schneider (OFA) · Wade Anderson (VP Eng) · Tim Thiessen (VP Sales)', 'Okuma America, the US arm of Okuma Japan, running a 17,000 sq ft booth with eleven machines and four Americas debuts, plus robot loaders, a tower pallet changer and an Intrinsic AI cell. Runs a formal Partners in Technology program for tooling and accessory vendors.', 'The only OEM at the show with a published, structured partner program for tooling companies. That turns a vague co-marketing wish into an application with a process. MULTUS runs Capto C6 and C8, the MU 5-axis series runs HSK-A63, and their automation push means presetting demand.', 'You have a Partners in Technology program, which is the reason I walked over. We build shrink fit, shrink machines and presetters, and we just opened a US branch. What does a tooling vendor have to show you to get in?', '{"Requirements and application process for Partners in Technology","Who chooses tooling for Okuma demo and tech-center machines","Does Okuma Factory Automation have a tool-setup story?"}', 'Large booth, heavy traffic. Go early or late in the day and ask for a partner-program contact by name rather than a demo.', true, false),
  ('mazak', 'Mazak', 'B', '{"338300"}', 'Machine OEM', 'Florence, KY', 'Largest live-cutting booth. CAT40 BIG-Plus, HSK-A63 on VARIAXIS, Capto on INTEGREX.', 'Dan Janka, President', 'The largest live-cutting booth at the show: more than ten machines including INTEGREX i-200ST NEO, HCN-5000 NEO, VARIAXIS C-700 and i-800T, QUICK TURN 350 and SYNCREX Swiss, plus multi-pallet systems, an Ez LOADER cobot and gantry loaders.', 'Mazak spans every interface we make: CAT40 and BT40 BIG-Plus on the machining centers, HSK-A63 on VARIAXIS 5-axis, Capto on INTEGREX. Their Palletech and MPP cells run unattended, which is the presetting argument. Also the single best booth for reading which holder brands an OEM trusts in its own spindles.', 'You are running ten machines live here, and every one has somebody''s holders in the spindle. We make shrink fit, and unlike the brand you are running we also make the machine that shrinks them. Who picks tooling for these demos?', '{"Who specifies tooling for demo and tech-center machines","Free starter set for one Palletech or VARIAXIS demo","Photograph what is in the spindles and the ATC carousels"}', 'Enormous booth, constant crowd. This is as much a recon stop as a pitch: the spindle contents are the intelligence.', true, false),
  ('makino', 'Makino', 'B', '{"338519"}', 'Machine OEM', 'Mason, OH', 'HSK-A63/A100 house (a-series, DA500). Aerospace and die-mold, where shrink fit is default.', null, 'Showing a51nx, a81nx, a630iT, V300, MAG3-EX, DA500 and EDAF EDM with pallet systems and cell control. Aerospace, die and mold, and medical are their core markets.', 'Makino is an HSK-A63 and A100 house and their customers machine titanium and hardened steel where holder rigidity and runout decide tool life. Shrink fit is not an upsell here, it is the default. Their pallet systems also imply offline tool setup.', 'Your customers are cutting titanium with long reaches, which is where shrink fit stops being optional. We make HSK-A63 and A100 shrink holders and the machine that heats them. What tooling goes out with an a-series install?', '{"Tooling package on a-series and DA500 installs","Whether their cell control integrates presetter data","Free starter set for a tech-center machine"}', 'Premium brand with premium customers. Lead with the inspection data and the slim-profile specials, not with price.', true, false),
  ('hurco', 'Hurco · Takumi · Milltronics', 'B', '{"338319"}', 'Machine OEM', 'Indianapolis, IN', 'Takumi U800 is a native HSK-A63, 20,000 rpm 5-axis with a 64/96 ATC. Perfect shrink-fit demo platform.', null, 'Hurco, Takumi and Milltronics share one booth. Hurco is debuting the BM500U 5-axis with an 8-station pallet changer, a 15,000 rpm BIG-Plus spindle and a 60 to 96 tool changer; Takumi shows the U800 5-axis at 20,000 rpm HSK-63A with a 64 to 96 tool ATC.', 'Three brands, one conversation, and the Takumi U800 is a native HSK-A63 high-speed 5-axis: the perfect machine to demonstrate a shrink holder on. A 96-position tool changer also means 96 assembled tools, which is a presetting and shrink-machine argument by itself.', 'A 96-tool changer means somebody assembles 96 tools. Shrink fit at our price makes that affordable, and the U800 at 20,000 rpm is exactly where a balanced shrink holder beats a collet chuck. Can we put holders on the U800 demo?', '{"Holders on the Takumi U800 demo","Who buys tooling for three brands: one buyer or three?","ProCobot automation and tool-setup demand"}', 'Three brands in one booth means three sets of staff. Find out early who covers which.', true, false),
  ('dn', 'DN Solutions', 'B', '{"338919"}', 'Machine OEM', 'Pine Brook, NJ', 'BT40/CAT40 BIG-Plus, Capto C6, HSK on DVF. Tuesday reception 4–7 pm.', null, 'DN Solutions America (formerly Doosan Machine Tools) showing DNX 2100SB with a 12,000 rpm Capto C6 milling spindle, DVF 5000, PUMA SMX 2600ST, DHF 5500, DNM 5700, NHP 4000 and pallet pools. Booth reception Tuesday 4 to 7 pm and a daily 4 pm happy hour.', 'High-volume value OEM with the largest dealer network of any brand we can realistically reach, and the dealers are in the booth. DVF 5-axis carries HSK options and the mill-turns run Capto C6.', 'Your dealers are standing in this booth and they all quote tooling with machines. We are the shrink-fit line that fits a DVF customer''s budget. Which dealer should I be talking to first?', '{"Dealer introductions inside the booth","Tooling package on DVF 5-axis installs","Attend the Tuesday reception"}', 'The dealers, not DN itself, are the real target here. Go at reception time.', true, false),
  ('kitamura', 'Kitamura', 'B', '{"338520"}', 'Machine OEM', 'Wheeling, IL', 'BBT40/BBT50, 82 distributors. Ask for distributor introductions.', null, 'US arm of Kitamura Machinery, ninety years old, selling VMCs, HMCs and 5-axis through a network of roughly 82 distributors across North America.', 'Eighty-two distributors is eighty-two potential tooling conversations, and Kitamura machines run BBT40 and BBT50 dual-contact with HSK options. An OEM with a big dealer network is an introduction engine.', 'You sell through more than eighty distributors. We need distributors and we are not competing with anything you make. Would you point us at the ones who sell tooling as well as machines?', '{"Which of their distributors also sell tooling","Tooling package on Kitamura installs","BBT dual-contact holder compatibility discussion"}', 'Ask for introductions, not for a corporate deal. Distributor names are the deliverable.', true, false),
  ('matsuura', 'Matsuura', 'B', '{"338630"}', 'Machine OEM', 'St. Paul, MN', 'Multi-pallet lights-out; presetting buyer by definition.', null, 'Matsuura Machinery USA showing the MX-850 PC4 5-axis with a four-pallet system and Cublex mill-turn. Their whole proposition is lights-out multi-pallet machining.', 'Lights-out machining is the strongest presetting argument that exists: an unattended machine cannot fix a bad tool offset at 2 am. Matsuura customers run BT40 and HSK-A63 and already accept that setup happens offline.', 'Your customers run unattended overnight, which means every tool has to be right before the lights go off. That is a presetter and a shrink machine, not a hope. How do your customers handle tool setup today?', '{"How Matsuura customers preset tools today","Presetter plus shrink station as an install add-on","Free starter set for a demo machine"}', 'Sold through Productivity Inc. in the Upper Midwest. Coordinate the two conversations.', true, false),
  ('hermle', 'Hermle', 'B', '{"339121"}', 'Machine OEM', 'Franklin, WI', 'Pure HSK-A63/A100. ZM tool magazines create tool-assembly demand.', null, 'Hermle USA showing C 22 MT GEN2 and C 62 U MT North American debuts, C 12 GEN2 with an RS 05-2 robot, C 250 GEN2 and C 400 GEN2, plus the ZM 30 tool magazine.', 'A pure HSK-A63 and A100 platform: there is no other interface to talk about, which makes the conversation simple. Large ZM tool magazines mean large assembled-tool inventories, which is our machine and presetter argument.', 'Everything you build takes HSK, and a ZM 30 magazine means thirty assembled tools sitting ready. We make HSK-A63 and A100 shrink fit and the machine to assemble them. Who handles tooling for your demos?', '{"Tooling on Hermle demo machines","How their customers assemble tools for large magazines","German-engineering objection: how do they evaluate a non-German supplier?"}', 'Premium German brand, premium customers. Expect the origin objection in its strongest form.', true, false),
  ('datron', 'Datron', 'B', '{"338248"}', 'Machine OEM', 'Milford, NH', 'HSK-E25/E32/E40 high-speed spindles. Small shrink fit is the sweet spot.', null, 'DATRON USA showing M8Cube, MLCube, MXCube and neo high-speed machining centers with ATC and probing, aimed at aluminum, dental, medical and electronics.', 'DATRON runs HSK-E25, E32 and E40 at very high rpm, the small-diameter end where shrink fit is the only serious option and where most suppliers do not stock inventory. A niche we can own without fighting Haimer head-on.', 'HSK-E32 and E40 at high rpm is a size range most holder companies treat as an afterthought. We make it, balanced, with slim profiles. What do your customers use today?', '{"What small-HSK holders their customers buy today","Free starter set of HSK-E32 and E40","Their view on runout at 40,000 rpm and above"}', 'Small-diameter work is unforgiving. Bring real runout numbers or do not bring the subject up.', true, false),
  ('kern', 'Kern Precision', 'B', '{"338719"}', 'Machine OEM', 'Wixom, MI', 'HSK-E40/A63 micro-milling; shrink fit standard.', null, 'Kern Precision, the US arm of Kern Microtechnik, showing ultra-precision 3 and 5 axis machining centers built for 24/7 operation in medical, optics and watch work.', 'Sub-micron machining where shrink fit is standard and HSK-E40 and A63 dominate. Small volume, very high standards: a reference customer here is worth more than a distributor elsewhere.', 'Your customers measure in tenths of a micron, so I will not talk about price. I want to know what runout and balance you would need to see before a Kern customer would consider a new holder brand.', '{"Their acceptance criteria for a holder brand","Whether they would test a sample set","Which holders their customers run today"}', 'This is a credibility conversation, not a sales one. If they say the numbers are not good enough, that is valuable.', true, false),
  ('jtekt', 'JTEKT (Toyoda) · Mitsui Seiki', 'B', '{"338700"}', 'Machine OEM', 'Arlington Heights, IL', 'CAT40/50 BIG-Plus and HSK; Mitsui HSK-E25 at 50,000 rpm.', null, 'JTEKT (Toyoda) shares a booth with Mitsui Seiki: HMCs, VMCs, grinding and pallet pools from JTEKT; the PJ 303X at 50,000 rpm HSK-E25 from Mitsui Seiki.', 'Two very different customers at one stand. Toyoda is CAT40, CAT50 and BIG-Plus volume production; Mitsui Seiki is ultra-precision HSK-E25 and A63. Both ends of our range in one booth.', 'You have Toyoda volume production on one side and Mitsui ultra-precision on the other, which happens to be both ends of what we make. Who handles tooling for each?', '{"Separate tooling contacts for Toyoda and Mitsui Seiki","Pallet-pool customers and offline tool setup","HSK-E25 at 50,000 rpm: what holder do they run?"}', 'Shared booth: confirm which company you are actually talking to before pitching.', true, false),
  ('mcm', 'MC Machinery (Mitsubishi EDM · Roku-Roku)', 'B', '{"338129"}', 'Machine OEM', 'Wood Dale, IL', 'Roku-Roku HSK-E32/E40 graphite and hard milling, shrink fit native.', 'Alan Hallmann, NA Sales Mgr', 'MC Machinery Systems, the Mitsubishi EDM and machine tool arm, showing the SG70 sinker, an MG-series wire debut and the Roku-Roku HC658III high-speed milling machine.', 'Roku-Roku is graphite and hard-milling at high rpm on HSK-E32 and E40, where shrink fit is native and electrode work demands slim profiles. A narrow but perfectly matched product fit.', 'Roku-Roku customers cut graphite electrodes with long slim tools, which is the hardest case for a collet chuck and the easiest case for shrink fit. What do they run now?', '{"Roku-Roku customer tooling today","Slim-profile shrink holders for electrode work","Free starter set for the demo machine"}', 'EDM-heavy booth; the milling side may be one or two people. Ask for the Roku-Roku product manager.', true, false),
  ('index', 'INDEX', 'B', '{"339119"}', 'Machine OEM', 'Noblesville, IN', 'Shows HORN tooling reps inside its booth: the precedent for a holder brand on an OEM stand.', 'Michael Huggett, President & CEO', 'INDEX and TRAUB, showing the TRAUB MS12-4 multispindle and INDEX G160 turn-mill as North American debuts, with live cutting. HORN tooling representatives work inside their booth.', 'INDEX hosts a tooling manufacturer''s people inside its own booth. That is the exact arrangement we want with somebody, and it proves the model exists at this show. Their G-series runs Capto and HSK-T.', 'You have HORN people standing in your booth, which is the arrangement every tooling company wants. How did that start, and what would a new tooling partner have to bring?', '{"How the HORN in-booth partnership works","Capto and HSK-T holder needs on the G-series","Who owns tooling partnerships"}', 'Use them as a template even if nothing comes of it. The answer to "how did that start" is reusable everywhere.', true, false),
  ('smec', 'SMEC America', 'B', '{"338948"}', 'Machine OEM', 'Pine Brook, NJ', 'Capto C6 + BT40 value segment. Less crowded booth, same bundle ask.', null, 'SMEC America, formerly Samsung Machine Tools, debuting the STX 2600ST twin-spindle B-axis mill-turn with Capto C6, alongside machining centers.', 'Korean value-segment OEM whose customers are price-sensitive in exactly the way ours are. Less booth traffic than the Japanese brands, so a longer conversation is possible.', 'Your customers buy on value and so do ours. A tooling package that does not double the cost of the machine is worth something to both of us. Who quotes tooling with an SMEC machine?', '{"Tooling package on SMEC installs","Their US dealer list","Capto C6 holder demand"}', 'Booth number differs between the directory (338948) and one press listing (338599). Check the directory on site.', true, false),
  ('hwacheon', 'Hwacheon', 'B', '{"339148"}', 'Machine OEM', 'Carol Stream, IL', 'BT40/BT50 job shops; Productivity is their dealer.', null, 'Hwacheon Machinery America, Korean VMCs and lathes sold through regional dealers including Productivity Inc.', 'BT40 and BT50 job-shop machines at value pricing. Their dealers overlap with dealers we are already targeting, so a warm word here helps the dealer conversation.', 'Your machines go to shops that count every dollar, which is our customer exactly. Which of your dealers also push tooling?', '{"Dealer names who sell tooling","Tooling on Hwacheon demo machines","Their view on Chinese-made accessories"}', 'Quieter booth, easy access. Good warm-up conversation early in the day.', true, false),
  ('heller', 'Heller', 'B', '{"338930"}', 'Machine OEM', 'Troy, MI', 'HSK-A63/A100 automotive and aero. Ellison co-staffs.', null, 'Heller Machine Tools showing the HF 3500 mill-turn with automatic pallet changer and the F 6000 5-axis, aimed at automotive and aerospace volume production.', 'HSK-A63 and A100 production machining with high tool counts per machine. Ellison co-staffs their booth, so it doubles as a second shot at the Ellison conversation.', 'Production HSK work burns through holders and every one has to be interchangeable. We make HSK-A63 and A100 to spec with certificates per holder. Who handles tooling standards for your installs?', '{"Tooling standards for production installs","Second run at Ellison staff in the booth","Volume pricing expectations"}', 'Automotive production buyers care about repeatability across hundreds of holders, not single-piece runout.', true, false),
  ('chiron', 'Chiron', 'B', '{"339265"}', 'Machine OEM', 'Charlotte, NC', 'HSK-A63 standard; automotive and medical turnkey cells.', null, 'Chiron America showing vertical and mill-turn machining centers with turnkey automation for automotive and medical.', 'HSK-A63 standard across the line and turnkey cells that include tooling packages by definition. If Chiron builds a turnkey, somebody supplies the holders in it.', 'When you deliver a turnkey cell, the holders are part of the package. Who supplies them today and what would it take to be on that list?', '{"Who supplies holders in Chiron turnkeys","Approved-supplier requirements","HSK-A63 volume pricing"}', 'Turnkey supply means qualification paperwork. Ask what documentation they require.', true, false),
  ('haas', 'Haas Automation', 'B', '{"338100"}', 'Machine OEM', 'Oxnard, CA', 'Haas sells its own shrink holders and machine. The real target is the HFO network. After-Hours event Tuesday 5–6.', null, 'The largest US machine tool builder by unit volume, with daily $5,000 tooling giveaways and an After-Hours event Tuesday 5 to 6 pm. Sells its own shrink-fit holders and a shrink machine through Haas Tooling, and distributes exclusively through the Haas Factory Outlet network.', 'Haas is simultaneously the biggest installed base of CAT40 and BT40 machines in America and a direct competitor through Haas Tooling. The real target is not Haas: it is the HFO network in the booth, and the pricing intelligence at the Haas Tooling stand.', '(To HFO staff, not Haas corporate.) Your customers buy Haas because of value. Haas Tooling does not make a shrink machine at our price. What do your customers do when they want shrink fit?', '{"Identify HFO dealers in the booth by territory","Haas Tooling shrink-fit pricing at 432212","Whether HFOs can sell non-Haas tooling"}', 'Do not pitch Haas corporate; they compete. Work the HFO people and the tooling price list.', true, false),
  ('haastool', 'Haas Tooling', 'B', '{"432212"}', 'Competitor', 'Oxnard, CA', 'Study Haas own-brand shrink fit pricing. Competitor-channel.', null, 'Haas Tooling, the in-house tooling brand: holders, collets, cutters and a shrink-fit machine sold direct to Haas owners at aggressive prices.', 'Pure recon. Haas Tooling is the price floor that every American job shop now anchors on, and their shrink machine price is the number our $6,785 has to beat or justify.', '(Recon only.) What does the shrink machine run, and what is the lead time on a CAT40 shrink holder right now?', '{"Shrink machine price and specification","CAT40 and BT40 shrink holder prices","Stated runout and balance specs"}', 'Do not pitch. Photograph the price card if they allow it and move on.', true, false),
  ('phillips', 'Phillips Corp (Haas Factory Outlet)', 'B', '{"338272"}', 'Dealer', 'Hanover, MD', 'Only HFO with its own booth. Tooling add-ons on Haas installs.', null, 'Phillips Corporation, a Haas Factory Outlet covering the Mid-Atlantic and Southeast, plus Phillips Additive and machine-tool services. One of the few HFOs with its own booth.', 'The only practical way to reach the HFO network in a booth setting. Haas owners are exactly the shop that cannot justify a Haimer cell but could justify ours.', 'Your Haas customers want shrink fit and cannot spend twenty thousand dollars getting into it. We sell the machine at under seven. Can an HFO sell non-Haas tooling?', '{"Can HFOs sell third-party tooling?","Who else in the HFO network to approach","Interest in a demo shrink cell"}', 'HFO contracts may restrict third-party tooling. Find out before building a plan around it.', true, false),
  ('trak', 'TRAK Machine Tools', 'B', '{"338032"}', 'Machine OEM', 'Rancho Dominguez, CA', 'CAT40 job-shop entry segment, direct sales CA/TX/Midwest. Starter-cell pitch.', null, 'TRAK Machine Tools (Southwestern Industries), maker of ProtoTRAK-controlled toolroom mills, bed mills and lathes, sold direct by a field sales force in California, Texas and the Midwest.', 'Small-lot and toolroom shops running CAT40, sold direct rather than through dealers, and headquartered in our own metro area. Direct sales means one conversation reaches the whole channel.', 'You sell direct, which means one decision covers your whole field team. Your toolroom customers are exactly the shops that have never owned a shrink machine because it cost more than their mill.', '{"Would their field sales carry a tooling add-on?","Toolroom customer appetite for a sub-$7K shrink cell","Local Southern California pilot"}', 'Their customers are small. Volume per account is low; the play is breadth through their sales force.', true, false),
  ('kent', 'Kent USA', 'B', '{"339444"}', 'Machine OEM', 'Tustin, CA', 'CAT40 entry segment.', null, 'KENT USA, importer and builder of manual and CNC mills, lathes and grinders at the entry end of the market, headquartered in Southern California.', 'Entry-segment CAT40 machines, Southern California base, price-driven customers. Easy geography, easy price conversation, low complexity.', 'We are both in Southern California and we both sell to shops that count dollars. Would your customers buy a shrink cell if it cost less than their vise set?', '{"Tooling add-ons with Kent machines","Local pilot customer","Their accessory sourcing today"}', 'Very price-driven. Do not lead with certificates; lead with the bundle price.', true, false),
  ('haimer', 'HAIMER USA', 'C', '{"431510"}', 'Competitor', 'Villa Park, IL (parent: Igenhausen, Germany)', 'The full shrink ecosystem plus Automation Cube One. Get Power Clamp pricing and lead times. Do not pitch.', 'Brendt Holden, President & CEO', 'Family-owned German manufacturer, roughly 1,000 employees, and the reference brand for shrink fit worldwide: shrink chucks, Power Clamp shrink machines, Tool Dynamic balancers, Microset presetters, Safe-Lock pull-out protection and the new Automation Cube One robotic shrink and preset cell.', 'Our direct competitor and the benchmark every customer will name. Everything we need to know about American expectations for price, lead time and service is visible at this booth. They are also the company whose price increases created the opening we are walking into.', '(Recon only.) I am looking at shrink fit for a shop in California. What is the lead time on a special gauge length HSK100 right now, and what does a Power Clamp Economic run?', '{"Power Clamp pricing across the range","Lead time on specials and non-stock sizes","Photograph the Automation Cube One cell","Who they sell through in the western US"}', 'Do not pitch, do not identify as a competitor unprompted. Ask customer questions and listen. Their answers on lead time are our entire differentiation.', true, false),
  ('big', 'BIG DAISHOWA', 'C', '{"431610"}', 'Competitor', 'Hoffman Estates, IL (parent: Osaka, Japan)', 'BIG-Plus dual contact, Speroni presetters, tool-assembly automation. Hoffman Estates, IL.', 'Jack Burley, President/COO · Michael Herman, VP Sales', 'BIG DAISHOWA, formerly BIG KAISER, selling BIG-Plus dual-contact holders, Kaiser boring tools, Speroni presetters, Unilock zero-point workholding and tool-assembly automation from a 33,000 sq ft US facility.', 'The other premium incumbent, and the owner of the BIG-Plus dual-contact standard that Haas, Hurco, JTEKT and many others build spindles to. Understanding how they position dual contact against plain CAT is directly useful for our own sales story.', '(Recon only.) How much difference does BIG-Plus actually make on a 15,000 rpm CAT40 spindle, and does it require a special holder for every machine?', '{"BIG-Plus positioning against standard CAT40","Speroni presetter pricing tiers","Their tool-assembly automation demo"}', 'Very technically strong staff. Ask genuine engineering questions and they will teach you the objections we will face.', true, false),
  ('zoller', 'ZOLLER', 'C', '{"432018"}', 'Competitor', 'Ann Arbor, MI (parent: Pleidelsheim, Germany)', 'powerShrink, roboBox, micBox debut, TMS. Toolroom of the Year award Thursday 3:30 pm at the booth draws every toolroom manager on the floor. Be there.', 'Alexander Zoller, President', 'The global leader in tool presetting and tool management: venturion, smile and redomatic presetters, powerShrink shrink machines, toolBalancer, roboBox robotic tool assembly, the new micBox insert automation, and TMS tool management software. Hosts the Toolroom of the Year award at the booth Thursday at 3:30 pm.', 'Our presetting and tool-setup-automation competitor, and the company defining what lights-out tool setup means. Also the single best crowd event of the week: every toolroom manager on the floor gathers at their booth Thursday afternoon.', '(Recon only.) How does roboBox handle a mixed batch, and what does an entry presetter actually cost once the software is included?', '{"Entry presetter pricing including software licensing","Whether TMS software is subscription or perpetual","Photograph roboBox and micBox in operation","Be at the Toolroom of the Year award Thursday 15:30"}', 'Software licensing is their weak point and our opening: no-subscription presetting is a real differentiator. Find out the actual terms.', true, false),
  ('schunk', 'SCHUNK', 'C', '{"432010","236700"}', 'Competitor', 'Morrisville, NC (parent: Lauffen, Germany)', 'Hydraulic and polygonal chucks are the "no machine needed" objection. Learn the pitch.', null, 'Family-owned German technology company, roughly 3,700 employees, covering toolholding (TENDO hydraulic, TRIBOS polygonal, CELSIO shrink), workholding, grippers and automation. Present in both the Tooling hall and the Emerging Technology Center.', 'The source of the strongest competing argument against shrink fit: a TENDO hydraulic chuck needs no machine, no heat and no waiting. Every shop we pitch will have heard it. We need their exact wording.', '(Recon only.) Why would a shop choose TENDO over shrink fit, and where does hydraulic actually lose?', '{"Their hydraulic-versus-shrink talking points, verbatim","TENDO pricing versus shrink holder pricing","iTENDO sensor chuck: is anyone buying it?"}', 'They will answer the hydraulic-versus-shrink question honestly because they sell both. Write down the exact phrasing.', true, false),
  ('kennametal', 'Kennametal', 'C', '{"431800"}', 'Competitor', 'Pittsburgh, PA', 'Live 5-axis "Next Level Shop" with OEM machines and a motorcycle build. This is the co-demo model.', null, 'NYSE-listed global cutting tool manufacturer running a ''Next Level Shop'' experience with live 5-axis machining and a motorcycle build, showing KM and HSK holders, WIDIA and ToolBOSS vending.', 'Less a holder competitor than a demonstration of the co-marketing model we want to copy: a tooling brand running live cutting on other people''s machines with a crowd-drawing theme. Study the mechanics of how the booth is staged and who their machine partners are.', '(Recon only.) Whose machines are these, and how does a partnership like this come together?', '{"Which OEMs partnered on the live machines and how","How the booth is staffed and staged","ToolBOSS vending: how tooling reaches the operator"}', 'Treat this as a field trip. The lesson is the staging, not the holders.', true, false),
  ('regofix', 'REGO-FIX', 'C', '{"431822"}', 'Competitor', 'Whitestown, IN (parent: Tenniken, Switzerland)', 'powRgrip press-fit is positioned against shrink fit. Learn their anti-shrink talking points so you can answer them.', null, 'Swiss family-owned maker of ER collet systems (they invented the ER collet), the powRgrip press-fit toolholding system, reCool through-coolant and secuRgrip pull-out protection. Sponsors an IndyCar entry.', 'powRgrip is positioned explicitly as the alternative to shrink fit: press-fit clamping with no heat, a cheap bench unit and fast changeover. It is the second-strongest objection we will face after hydraulic, and their booth is where the argument is made best.', '(Recon only.) What does powRgrip do better than shrink fit, and what does it give up?', '{"Their anti-shrink argument, verbatim","powRgrip unit and holder pricing","Runout and clamping force claims versus shrink"}', 'They will happily explain why shrink fit is inferior. That is the point of going. Take notes, argue nothing.', true, false),
  ('mst', 'MST Corporation', 'C', '{"431576"}', 'Competitor', 'Osaka / Nara, Japan', 'Premium slim shrink fit from Japan, sold through Yamazen.', null, 'Japanese manufacturer of premium slim-profile shrink-fit holders (SLIMLINE), angle heads and workholding fixtures, distributed in the US partly through Yamazen.', 'The closest product analogue to what we make, at the premium end. Their slim profiles are the technical bar for 5-axis clearance, and understanding their US price and lead time tells us exactly how much room exists beneath them.', '(Recon only.) What is the lead time on a SLIMLINE HSK63A in the US, and who stocks them?', '{"US pricing and lead time","Who distributes them besides Yamazen","Slim profile dimensions to benchmark against ours"}', 'Yamazen is a Tier A target and MST''s distributor. Be careful what you say at each booth.', true, false),
  ('brighttools', 'Bright-Tools (Shandong Jinjie)', 'C', '{"431370"}', 'Competitor', 'Dezhou, Shandong, China', 'Direct Chinese competitor in our aisle. Compare pricing; explore non-compete cooperation on US logistics.', null, 'Shandong Jinjie Machinery, trading as Bright Tools, describing itself as one of the largest toolholder manufacturers in China: collet, power milling, hydraulic and shrink-fit holders in BT, CAT, SK and HSK, plus VDI and BMT, with ODM capability.', 'A direct Chinese competitor in the same aisle with the same tariff exposure and the same origin objection. Also a potential ally: shared US warehousing, shared freight, or simply intelligence about which US distributors have already said no.', 'We are both Chinese, both here, both facing 41% duty. Which American distributors have taken your calls?', '{"Which US distributors they have signed or lost","Do they hold US inventory, and where?","Their US price points on HSK63A shrink fit"}', 'Competitor first, ally second. Share general market observations, not customer names.', true, false),
  ('ounuowei', 'Shandong Ounuowei', 'C', '{"431264"}', 'Competitor', 'Shandong, China', 'Shrink fit chucks, PSC/HSK. Direct Chinese competitor.', null, 'Shandong Ounuowei Numerical Control Tool, a Chinese national high-tech enterprise making mid to high-end CNC tooling: PSC, HSK, BBT and BT holders, shrink-fit chucks, hydraulic holders, ER and SK collets and damping bars.', 'Direct Chinese competitor with an overlapping catalogue, including shrink fit and damping bars. Useful for price benchmarking and for understanding which segments of the Chinese field are already in the US.', 'What are you quoting on HSK63A shrink fit for US customers, and are you shipping from China or from stock here?', '{"Their US price points","Whether they hold US stock","Which trade shows they are doing this year"}', 'Direct overlap. Keep our channel plans to ourselves.', true, false),
  ('evermore', 'Evermore Machine (Taiwan)', 'C', '{"431756"}', 'Competitor', 'Taiwan', 'OEM supplier to big brands, pays 15% duty. That is the private-label competitor.', null, 'Taiwanese manufacturer established 1979: keyless drill chucks, VDI and BMT live holders, CNC holders including HSK and PSC. Describes itself as a trusted OEM supplier to well-known brands.', 'The private-label competitor that matters most. Taiwan pays roughly 15% duty against our 41%, so on a pure landed-cost basis they beat us to any US brand looking for an OEM source. We need to know their price to know what we must beat on something other than price.', '(Recon only.) Do you do OEM programs for US brands, and what is a typical minimum order?', '{"Their OEM minimums and lead times","Approximate price level","Which US brands they supply, if they will say"}', 'This is the competitor our tariff disadvantage is measured against. Be realistic about what we learn here.', true, false),
  ('parfaite', 'Parfaite Tool (Taiwan)', 'C', '{"431771"}', 'Competitor', 'Taiwan', 'Spindles and holders.', null, 'Taiwanese maker of motorized spindles, CNC tool holders, grinding arbors and gear machining solutions, launching what it calls a first-of-its-kind tool clamping solution at this show.', 'Taiwanese competitor with a spindle business, which gives them a credible taper-accuracy story. Their new clamping launch is worth seeing because it may be a shrink-fit alternative.', '(Recon only.) What is the new clamping system, and how does it compare to shrink fit?', '{"What the new product actually is","Whether it competes with shrink fit","Their US distribution"}', 'New product launches get heavy booth traffic. Go early.', true, false),
  ('yg1', 'YG-1', 'C', '{"431400"}', 'Competitor', 'Vernon Hills, IL (parent: South Korea)', 'Korean brand that became a default second source via a Vernon Hills warehouse, 98% fill rate and "Best Value." Ask how they built distribution.', null, 'Korean cutting tool manufacturer with a long-established US arm in Vernon Hills, built on warehouse stock, a 98% fill rate and an explicit ''Best Value in the World'' position roughly 20 to 40% below Sandvik and Kennametal. Later acquired US brands to expand.', 'The best available template for an Asian manufacturer becoming a default second source in America. They did it with stock and fill rate rather than with price alone, and it took years. Their answer to ''how long'' calibrates our expectations.', 'You built a US business on stock and fill rate rather than on being cheapest. How long before distributors stopped treating you as the risky option?', '{"How long from US launch to distributor acceptance","Whether warehouse stock or field sales mattered more","What they would do differently now"}', 'Cutting tools, not holders, so minimal competitive tension. They will usually talk.', true, false),
  ('sandvik', 'Sandvik Coromant', 'C', '{"338348"}', 'Competitor', 'Mebane, NC (parent: Sweden)', 'Capto and CoroPlus tool-ID as the tool-management benchmark.', null, 'Sandvik Coromant, showing Coromant Capto modular tooling, CoroPlus tool management and identification, an interactive 3D simulation table and a VR tour.', 'Capto is the interface we do not yet serve, and CoroPlus is the benchmark for tool identification and data. If we want to talk to any OEM about tool data flowing from presetter to machine, this booth defines what good looks like.', '(Recon only.) How does CoroPlus get tool data from a presetter into the machine, and what standard does it use?', '{"How CoroPlus handles presetter-to-machine tool data","Whether ISO 13399 is genuinely used in practice","Capto adapter demand in the US"}', 'Huge booth, marketing-heavy. Ask for an applications engineer, not a demonstrator.', true, false),
  ('ceratizit', 'CERATIZIT USA', 'C', '{"431900"}', 'Competitor', 'Schaumburg, IL (parent: Plansee Group)', 'Holders and carbide; secondary competitor.', null, 'CERATIZIT USA, showing MaxiMill, WTX drills and MonsterMill cutting tools alongside toolholding from the Komet and WNT brands.', 'A secondary competitor whose holders ride along with a cutting tool catalogue. Useful for understanding how a full-line supplier prices holders as an attachment rather than a product.', '(Recon only.) Do customers buy your holders because of the holders, or because they are already buying the cutters?', '{"How holders are priced within a full-line catalogue","Their shrink-fit offering, if any","Distribution model"}', 'Low priority. Ten minutes if the day allows.', true, false),
  ('marposs', 'Marposs', 'C', '{"134324"}', 'Competitor', 'Auburn Hills, MI (parent: Italy)', 'In-machine tool setting is the alternative to offline presetting. Learn the objection.', null, 'Marposs, in-process gauging and measurement, listed in the IMTS directory under Tool Presetting Equipment.', 'In-machine tool measurement is the structural alternative to buying an offline presetter: why preset offline when the machine can measure the tool itself? This is the objection our presetter has to answer.', '(Recon only.) If a shop has in-machine tool measurement, why would they still buy an offline presetter?', '{"Their argument against offline presetting","Cycle-time cost of in-machine measurement","Price of in-machine tool setting"}', 'Their honest answer (spindle time is expensive) is also our best counter-argument. Get it in their words.', true, false),
  ('renishaw', 'Renishaw', 'C', '{"134314"}', 'Competitor', 'West Dundee, IL (parent: UK)', 'Probing and tool setting; listed under presetting.', null, 'Renishaw, probing, tool setting and metrology, across three booths in East and South.', 'Same structural question as Marposs: probes and laser tool setters are what a shop buys instead of a presetter. Renishaw is the volume brand for it, so their pitch is the one our customers will have heard.', '(Recon only.) Where does a laser tool setter stop being enough and a shop needs offline presetting?', '{"Where in-machine tool setting reaches its limits","Typical price of a tool setting system","Whether they see presetters as complementary"}', 'Three booths; the tool-setting people are not the CMM people. Ask specifically.', true, false),
  ('blum', 'Blum-Novotest', 'C', '{"134710"}', 'Competitor', 'Erlanger, KY (parent: Germany)', 'Laser tool measurement in the machine.', null, 'Blum-Novotest, laser measuring and tool monitoring systems for in-machine tool measurement and breakage detection.', 'The precision end of in-machine tool measurement. Same objection-research purpose as Marposs and Renishaw; one visit covers the category if time is short.', '(Recon only.) What accuracy do you actually achieve measuring a tool in the spindle versus offline?', '{"In-machine versus offline accuracy claims","Thermal effects on in-machine measurement","Price band"}', 'One of the three in-machine booths is enough if the week gets tight. Pick this one for the technical answer.', true, false),
  ('ur', 'Universal Robots', 'D', '{"236744"}', 'Automation', 'Ann Arbor, MI (parent: Odense, Denmark)', 'UR+ partner path for a cobot tool-assembly cell.', null, 'Universal Robots, the largest collaborative robot maker, showing PolyScope X and physical-AI cobot cells. Runs the UR+ ecosystem, a certified marketplace of third-party hardware and software that plugs into their arms.', 'UR+ is a published path for a component maker to become part of thousands of cobot installations without building a robot. A shrink and preset station that a UR arm can load is a UR+ candidate, and UR+ listing is marketing we could never buy.', 'We build a shrink-fit and presetting station. If a UR arm loaded and unloaded it, that is a tool-assembly cell nobody currently sells. What does UR+ certification involve?', '{"UR+ certification requirements and cost","Whether any partner already does tool assembly","Which integrators build machine-shop cells"}', 'Busy booth aimed at end users. Ask specifically for the UR+ partnership team.', true, false),
  ('vention', 'Vention', 'D', '{"236860"}', 'Automation', 'Montreal, Canada', 'Modular automation; fast cobot cell for a tool-assembly demo.', null, 'Modular automation platform: customers design a cell online from standard components and it ships as a kit, with plug-and-play machine tending.', 'The fastest way to build a demonstrable tool-assembly cell without engineering it ourselves. Useful as a supplier to us as much as a partner.', 'If we wanted a robot to load holders into a shrink machine and then onto a presetter, how fast could your platform build that cell?', '{"Cost and lead time for a small tool-assembly cell","Whether they would co-develop a demo","Their machine-shop customer base"}', 'Think of this as procurement for our own demo, not as a channel.', true, false),
  ('versabuilt', 'VersaBuilt Robotics', 'D', '{"236300"}', 'Automation', 'Boise, ID', 'Turnkey CNC cells for high-mix shops.', null, 'Turnkey robotic CNC cells for high-mix, low-volume shops, including cobot-tended mills and lathes.', 'High-mix shops change tools constantly, which is where tool setup time dominates. An integrator serving that segment has customers who feel our problem daily.', 'High-mix means constant tool changes. Do your customers ever ask you to automate the tool setup side, not just part loading?', '{"Whether customers ask about tool setup automation","Their typical customer size","Integration interest"}', 'Small company, practical people. Concrete questions work better than vision.', true, false),
  ('formic', 'Formic', 'D', '{"236329"}', 'Automation', 'Chicago, IL', 'Robots-as-a-service machine tending; lights-out shops.', null, 'Robots-as-a-service: machine tending automation with no capital expenditure, billed hourly.', 'Their model proves that shops will rent automation they cannot buy. The same logic could apply to a shrink and preset station, which is the same capital objection we already face.', 'Your customers cannot justify the capital for a robot, which is exactly why they cannot justify a shrink machine either. Has anyone asked you to bundle tool setup?', '{"Whether the RaaS model could extend to tool setup equipment","Their customer profile","Chicago-local customers worth meeting"}', 'Local Chicago company. Good for a follow-up visit after the show.', true, false),
  ('flexx', 'Flexxbotics', 'D', '{"236044"}', 'Software', 'Boston, MA', 'Robot-CNC connectivity software; tool-data layer.', null, 'Flexxbotics, robot-to-CNC connectivity and closed-loop production software linking robots, machines and quality systems.', 'The data layer between a presetter and a machine is exactly the kind of connection they build. If tool offsets are part of their closed loop, our presetter has a natural integration story.', 'Does your closed loop include tool data and offsets, or does it stop at part programs and quality?', '{"Whether tool offset data is in scope","Which controls they already integrate","Partner program"}', 'Software company at a machine show; the technical people are usually right there.', true, false),
  ('lang', 'Lang Technik', 'D', '{"236637"}', 'Automation', 'Sussex, WI (parent: Germany)', 'Zero-point and RoboTrex workholding automation.', null, 'Lang Technik, zero-point workholding, Makro-Grip vises and the RoboTrex automated pallet magazine system.', 'Workholding automation, the mirror image of tool automation. Their customers automate the part side and then discover the tool side is still manual. Complementary, not competing.', 'You automate the part side. Nobody automates the tool side. Do your RoboTrex customers ever ask what happens when the tool needs changing?', '{"Whether customers raise tool setup as the next bottleneck","Co-marketing to the same automated shops","Their US dealer network"}', 'Clean complementary story; worth a real conversation rather than a drive-by.', true, false),
  ('kuka', 'KUKA Robotics', 'D', '{"236807"}', 'Automation', 'Shelby Township, MI (parent: Augsburg, Germany)', 'Machine tending with Matsuura, SYIL, EMAG.', null, 'KUKA Robotics, showing machine tending with Matsuura, SYIL and EMAG partners.', 'Large integrator ecosystem. Less about KUKA itself and more about the system houses in their booth that build machine-shop cells.', 'Which of your integrators build cells for small machine shops? That is who we need to talk to about tool setup.', '{"Integrator names serving machine shops","Whether any cell includes tool assembly","Booth partners worth meeting"}', 'Go for the integrator names, not for KUKA.', true, false),
  ('erowa', 'EROWA', 'D', '{"339072"}', 'Automation', 'Arlington Heights, IL (parent: Switzerland)', 'Pallet and robot cells; also does ITS presetting.', null, 'EROWA Technology, palletization and robot cells with JMS software, plus the ITS tooling system used for presetting electrodes and workpieces.', 'Swiss precision automation with an existing presetting concept in their ITS system. They already understand offline setup as a philosophy, which shortens the conversation considerably.', 'You built EROWA around setting things up offline and loading them automatically. That is exactly our argument for tools rather than parts. Is tool assembly in scope for your cells?', '{"Whether tool assembly fits their cell philosophy","ITS presetting overlap","US customer base for cells"}', 'Premium Swiss brand. Technical credibility matters more than price here.', true, false),
  ('halter', 'Halter CNC Robotics', 'D', '{"339288"}', 'Automation', 'Chicago, IL (parent: Netherlands)', 'LoadAssistant tending; Ellison/Hartwig partner.', null, 'Halter CNC Robotics, LoadAssistant machine-tending cells with five-minute changeover, sold through dealers including Ellison and Hartwig.', 'Their dealers are our Tier A dealers, so a good conversation here strengthens those relationships. Fast-changeover cells mean frequent tool changes.', 'Ellison and Hartwig sell your cells and we are talking to both about tooling. Does tool setup ever come up when a customer automates part loading?', '{"Dealer overlap and warm introductions","Whether tool setup is a customer complaint","Chicago-local follow-up"}', 'Use this booth to reinforce the Ellison and Hartwig conversations.', true, false),
  ('robojob', 'RoboJob', 'D', '{"338982"}', 'Automation', 'Cincinnati, OH (parent: Belgium)', 'CNC tending across 100+ machine brands.', null, 'RoboJob, Turn-Assist and Mill-Assist machine tending with more than 2,000 installations across 100+ machine brands.', 'Volume installer of small-shop automation. Their installed base is full of shops that just discovered their bottleneck moved from part loading to tool setup.', 'Two thousand installations means two thousand shops that automated loading. Where did their bottleneck move to afterwards?', '{"Where the bottleneck moves after part-loading automation","Customer profile and size","Integration interest"}', 'Good source of market evidence for our own pitch, whether or not they partner.', true, false),
  ('melco', 'Mitsubishi Electric Automation', 'D', '{"338136"}', 'Automation', 'Vernon Hills, IL (parent: Japan)', 'LoadMate machine tending live.', 'David Simak, Product Manager', 'Mitsubishi Electric Automation, showing LoadMate Plus and ARIA machine-tending demos with robots and controls.', 'Controls plus robots in one company means they care how data moves between machine and cell, which is the presetter integration conversation.', 'When your robot tends a machine, how do tool offsets get in? Is that part of ARIA or is it still manual?', '{"How tool data enters their cells","Control integration for presetter output","Partner program"}', 'Large corporate booth; find an applications engineer.', true, false),
  ('tdm', 'TDM Systems', 'D', '{"133125"}', 'Software', 'Schaumburg, IL (parent: Sandvik)', 'Tool data and crib software; presetter-to-crib integration.', null, 'TDM Systems, tool data and lifecycle management software, including CRIBWISE for real-time tool crib control and Toolhive. Owned by Sandvik.', 'Every presetter needs somewhere to send its data. TDM is the most widely deployed destination in North America, so presetter compatibility with TDM is table stakes for selling into any larger shop.', 'If a shop buys a presetter, what does it have to output for TDM to accept it cleanly? We would rather build to your format than fight it.', '{"Data format and interface requirements for a presetter","Whether they certify or list compatible presetters","ISO 13399 in practice"}', 'Technical, not commercial. Bring a spec question and get a spec answer.', true, false),
  ('wintool', 'WinTool USA', 'D', '{"133368"}', 'Software', 'Elk Grove Village, IL (parent: Switzerland)', 'Tool management software.', null, 'WinTool USA, tool management and production resource management software for CNC shops.', 'Second-largest tool-data destination after TDM. Same compatibility question, smaller company, easier access.', 'What does a presetter need to output for WinTool to import it without a custom script?', '{"Import format requirements","Presetters they already support","Partner listing"}', 'Small booth; a ten-minute technical conversation is enough.', true, false),
  ('cribmaster', 'CribMaster · Vidmar · LISTA', 'D', '{"431485"}', 'Distributor', 'Atlanta, GA (Stanley Black & Decker)', 'Tool vending and storage; tool-crib automation tie-in.', null, 'CribMaster vending with Vidmar and LISTA storage: industrial vending machines and tool cribs that dispense tooling at the point of use inside plants.', 'Vending is how consumable tooling reaches operators in larger plants, and holders are increasingly vended alongside inserts. Understanding what gets vended tells us where the reorder volume actually is.', 'Do shops vend toolholders, or only consumables? And who supplies what goes in the machine?', '{"Whether holders are vended in practice","Who decides what stocks a vending machine","Distributor relationships behind vending"}', 'Their customers are large plants, not job shops. Different buyer from our core.', true, false),
  ('huayan', 'Huayan Robotics', 'D', '{"236746"}', 'Ally', 'China', 'Fellow Chinese first-timer. Share notes, split intel.', null, 'Chinese collaborative robot maker presenting an intelligent manufacturing solution with machine tending, exhibiting at IMTS for the first time.', 'Another Chinese first-timer solving the same market-entry problem in an adjacent category. Free intelligence exchange with no competitive risk at all.', 'First IMTS for you too? What has surprised you most about how American customers react?', '{"What is working and not working for them at the show","Their US entry plan","Shared logistics or warehousing ideas"}', 'Pure information trade. Ten minutes, genuinely friendly.', true, false),
  ('hub', 'IMTS Machinists'' Hub (Practical Machinist)', 'M', '{"432638"}', 'Media', 'West hall 432638', 'Live talks, daily meetups and happy hours in our hall. Be there every afternoon. Ask the host for a guest slot.', null, 'The IMTS Machinists'' Hub, run by Practical Machinist: live talks, daily meetups and happy hours in the middle of the Tooling hall, drawing working machinists and small shop owners rather than executives.', 'The only place in the building where a company with no booth can become a familiar face. The audience is exactly our end user, and the hosts need guests for their daily segments.', 'We are a Chinese shrink-fit maker that just opened a US branch and came here without a booth to find out what American shops actually want. Is that a segment you would want?', '{"Ask the host for a five-minute guest slot by Wednesday","Happy hour times for each day","Who else is being interviewed"}', 'Show up every day before asking for anything. Be useful first.', true, false),
  ('shops', 'IMTS Shops Zone (Gardner / Modern Machine Shop)', 'M', '{"432634"}', 'Media', 'West hall 432634', 'MMS editors work from here. Free Manufacturing Connected founding-member signup. Ask Bill Caldwell about remnant digital ads.', null, 'The IMTS Shops Zone, run by Gardner Business Media (Modern Machine Shop), featuring Bridgeport Serial No. 1, shop-floor demonstrations and the launch of the Manufacturing Connected platform. MMS editors work from here.', 'Job shop owners gather here all day and MMS editors are physically present. Free founding-member signup for Manufacturing Connected is a legitimate reason to start a conversation.', 'We are a new US branch of a Chinese shrink-fit manufacturer, here without a booth. Is an editor around who covers toolholding?', '{"Sign up as a Manufacturing Connected founding member","Ask which MMS editor covers toolholding","Bill Caldwell on remnant digital ad inventory"}', 'Editors are working, not selling. Be brief, be specific, leave a card.', true, false),
  ('cte', 'Cutting Tool Engineering', 'M', '{"432313"}', 'Media', 'West hall 432313', 'Writes dozens of Tooling-hall briefs. Pitch the "China shrink-fit maker opens US branch" story in one paragraph.', null, 'Cutting Tool Engineering magazine, which publishes dozens of booth briefs covering the Tooling and Workholding hall around the show.', 'The trade publication whose readership is precisely our buyer, physically present in our hall, actively looking for tooling stories during show week.', 'A Chinese shrink-fit manufacturer opened a US branch and came to IMTS without a booth to find out what American shops want. That is the story, and I can give you the numbers to go with it.', '{"Name and email of the editor covering toolholding","Whether they take post-show submissions","What they need: photos, specs, a quote"}', 'Pitch the angle, not the product. The no-booth angle is what makes it a story.', true, false),
  ('park', 'IMTS Community Park (G28)', 'M', '{"432200"}', 'Media', 'West hall 432200', 'Cornhole and expert conversations; a gathering point in our hall.', null, 'IMTS Community Park, run by AMT and G28: cornhole, RC crawlers and informal industry-expert conversations in an open seating area in the West hall.', 'A designed loitering space in our own hall. Low-pressure conversations with whoever sits down, and a legitimate place to bring someone met in an aisle.', '(Informal.) What brings you to the show this year?', '{"Use as a meeting point for warm contacts","Listen for shop owners talking about tooling","Rest stop between aisles"}', 'Not a pitch venue. Use it to continue conversations that started elsewhere.', true, false),
  ('showcase', 'Manufacturing Showcase (GIE Media)', 'M', '{"432636"}', 'Media', 'West hall 432636', 'Kratos drones; aero and defense crowd magnet next to the Tooling hall.', null, 'The IMTS Manufacturing Showcase, run by GIE Media, displaying Kratos XQ-58 Valkyrie and other unmanned aircraft alongside automation cells, next to the Tooling hall.', 'A crowd magnet that pulls aerospace and defense visitors into our hall. Defense and aerospace shops are the heaviest HSK and shrink-fit users in the country.', '(To visitors, not staff.) Are you machining parts like this? What are you holding your cutters in?', '{"Work the crowd, not the exhibit","Identify aerospace and defense shop badges","Note which primes are represented"}', 'The exhibit is the bait; the people looking at it are the target.', true, false),
  ('techhub', 'IMTS+ Technology Hubs', 'M', '{"134476","338164"}', 'Media', 'East 134476 · South 338164', 'Ask whether non-exhibitor lightning slots exist. Probably no; asking costs nothing.', null, 'IMTS+ Technology Hubs: curated stages with seating in the East and South buildings where exhibitors give short presentations throughout the show.', 'A long-shot ask with no downside: find out whether any speaking slot is available to a non-exhibitor, now or in future years.', 'Are any of these slots open to companies without a booth, this year or next?', '{"Whether non-exhibitor slots exist","Who programs the stage","Cost if any"}', 'Almost certainly exhibitors-only. One question, then move on.', true, false)
insert into visits (company_id, visited)
